// W6 · Plan — что сделать перед утренней сводкой.
// Нода: Code, режим «Run Once for All Items».
// Вход: все строки таблицы vacancies из «All rows».
// Выход: один item { expire, check }:
//   expire — карточки без решения (status = waiting) старше 3 дней → «⌛ устарела», кнопки убрать;
//   check  — хвосты: карточки без решения моложе 3 дней и ✅ без «📨 Отправил» (status = approved) →
//            открыть страницу на hh: закрылась — «🔒 закрыта на hh». Не больше 40 за раз, старые первыми.
// Время карточки — card_at (пишет W2), у старых строк — createdAt.

const DAY = 24 * 3600 * 1000;
const now = Date.now();
const rows = $input.all().map((i) => i.json).filter((r) => r.id);
const cardTime = (r) => Date.parse(r.card_at || r.createdAt) || now;

const waiting = rows.filter((r) => r.status === 'waiting');
const expire = waiting.filter((r) => now - cardTime(r) > 3 * DAY);
const expired = new Set(expire.map((r) => r.id));
const check = [...waiting.filter((r) => !expired.has(r.id)), ...rows.filter((r) => r.status === 'approved')]
  .sort((a, b) => cardTime(a) - cardTime(b))
  .slice(0, 40);

return [{ json: { expire, check } }];

// W6 · Expire rows — карточки без решения старше 3 дней: новый текст карточки без кнопок.
// Нода: Code, режим «Run Once for All Items». Вход: список expire из «Plan».
// Выход: { id, tg_message_id, text } → «Card: expired» (Telegram) → «Expired done» → «Save expired».

// Общий код карточки вакансии в Telegram: W2 «Format card» и W3 «Apply choice».
// В Code-ноду попадает при сборке: строка «// @include n8n/shared/card.js» заменяется этим файлом
// (scripts/build-workflows.mjs, scripts/run-code-node.mjs).

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const EXPERIENCE = { noExperience: 'без опыта', between1And3: '1–3 г.', between3And6: '3–6 л.', moreThan6: '6+ л.' };
const CURRENCY = { RUR: '₽', USD: '$', EUR: '€', KZT: '₸', BYR: 'Br', UZS: 'сум' };

// Решение нейросети (колонка decision)
const VERDICT = { apply: '🟢 apply', maybe: '🟡 maybe', skip: '🔴 skip', error: '⚠️ не оценено' };
// Кнопки пользователя: callback_data = v:<id строки>:<choice>, решение — в колонку my_decision.
// earlier — «📨 Уже откликался» (до бота, 07.10.2026): status = applied без письма и без applied_at,
// без «Почему?» и вне теневого режима (сравниваются только apply / maybe / skip)
const CHOICE = { apply: '✅ Откликнусь', maybe: '🤔 Возможно', skip: '❌ Мимо', earlier: '📨 Откликался раньше' };
const STATUS_BY_CHOICE = { apply: 'approved', maybe: 'maybe', skip: 'skipped', earlier: 'applied' };

const short = (n) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n));

function salary(r) {
  if (!r.salary_from && !r.salary_to) return '';
  const range =
    r.salary_from && r.salary_to
      ? `${short(r.salary_from)}–${short(r.salary_to)}`
      : r.salary_from
        ? `от ${short(r.salary_from)}`
        : `до ${short(r.salary_to)}`;
  return `💰 ${range} ${CURRENCY[r.currency] ?? r.currency ?? ''}${r.salary_gross ? ' до налогов' : ''}`;
}

// «Москва, Сербия, Грузия, Армения» → «Москва, Сербия +2»
function areas(s) {
  const list = String(s ?? '').split(', ').filter(Boolean);
  return list.length > 2 ? `${list.slice(0, 2).join(', ')} +${list.length - 2}` : list.join(', ');
}

// '2026-10-06T13:22:00+0300' → '06.10'
function published(s) {
  const m = String(s ?? '').match(/^\d{4}-(\d{2})-(\d{2})/);
  return m ? `${m[2]}.${m[1]}` : '';
}

// Момент в UTC (applied_at) → дата по Таиланду (UTC+7): '2026-10-06T21:17:55Z' → '07.10'
const thaiDate = (iso) => (Date.parse(iso) ? published(new Date(Date.parse(iso) + 7 * 3600 * 1000).toISOString()) : '');

// Итоговые состояния без кнопок: W3 «📨 Отправил», W6 «⌛ устарела» и «🔒 закрыта на hh»
const FINAL = { expired: '⌛ Устарела: 3 дня без решения', archived: '🔒 Вакансия закрыта на hh' };

// Текст карточки (Parse Mode = HTML). Строка «👤 …» появляется после нажатия кнопки,
// «📨 …» — после «Отправил» под письмом (W3, status = applied), FINAL — после W6
function cardText(r) {
  const date = published(r.published_at);
  const meta = [esc(r.company), salary(r), EXPERIENCE[r.experience] ?? '', esc(areas(r.areas)), date && `📅 ${date}`]
    .filter(Boolean)
    .join(' · ');
  const flags = [
    r.has_test && '📝 тест',
    r.letter_required && '✉️ письмо обязательно',
    r.responses != null && `👥 ${r.responses}`,
    r.error && `⚠️ ${esc(r.error)}`,
  ]
    .filter(Boolean)
    .join(' · ');
  const verdict = `🤖 ${VERDICT[r.decision] ?? esc(r.decision)}${r.llm_reason ? ` — ${esc(r.llm_reason)}` : ''}`;
  const mine = CHOICE[r.my_decision] ? `👤 ${CHOICE[r.my_decision]}` : '';
  // «📨 Откликался раньше» уже в строке «👤 …» — второй раз не пишем
  const sent =
    r.status === 'applied' && r.my_decision !== 'earlier'
      ? `📨 Отклик отправлен${r.applied_at ? ` ${thaiDate(r.applied_at)}` : ''}`
      : '';
  return [`<a href="${r.url}"><b>${esc(r.title)}</b></a>`, meta, flags, verdict, mine, sent, FINAL[r.status] ?? '']
    .filter(Boolean)
    .join('\n');
}

return $('Plan')
  .first()
  .json.expire.map((r) => ({ json: { id: r.id, tg_message_id: r.tg_message_id, text: cardText({ ...r, status: 'expired' }) } }));

// W6 · Expired done — status = expired для всех устаревших (даже если Telegram не дал изменить карточку).
// Нода: Code, режим «Run Once for All Items». Выход: обновления для «Save expired».

return $('Expire rows')
  .all()
  .map((i) => ({ json: { id: i.json.id, status: 'expired' } }));

// W6 · Check candidates — хвосты, которые надо проверить на hh (список check из «Plan»).
// Нода: Code, режим «Run Once for All Items». Выход: { id, url } → HTTP Request «Vacancy page».

return $('Plan')
  .first()
  .json.check.map((r) => ({ json: { id: r.id, url: r.url } }));

// W6 · Archive status — какие вакансии из хвостов закрылись на hh.
// Нода: Code, режим «Run Once for All Items».
// Вход: ответы «Vacancy page» по порядку списка check из «Plan».
// Закрыта: страница отдаёт 404/410 (вакансию удалили) или в ней status.archived / closedForApplicants.
// Не ответила, капча и т. п. — не трогаем, проверим завтра.
// Выход: только закрытые { id, tg_message_id, tg_letter_id, cardText, letterText } → карточка и письмо без кнопок.

// Общий код карточки вакансии в Telegram: W2 «Format card» и W3 «Apply choice».
// В Code-ноду попадает при сборке: строка «// @include n8n/shared/card.js» заменяется этим файлом
// (scripts/build-workflows.mjs, scripts/run-code-node.mjs).

