  const meta = [esc(r.company), salary(r), EXPERIENCE[r.experience] ?? '', esc(areas(r.areas)), date && `📅 ${date}`]
    .filter(Boolean)
    .join(' · ');
  const flags = [
    r.has_test && '📝 тест',
    r.letter_required && '✉️ письмо обязательно',
    r.responses != null && `👥 ${r.responses}`,
    r.error && `⚠️ ${esc(r.error)}`,
  ]
    .filter(Boolean)
    .join(' · ');
  const verdict = `🤖 ${VERDICT[r.decision] ?? esc(r.decision)}${r.llm_reason ? ` — ${esc(r.llm_reason)}` : ''}`;
  const mine = CHOICE[r.my_decision] ? `👤 ${CHOICE[r.my_decision]}` : '';
  // «📨 Откликался раньше» уже в строке «👤 …» — второй раз не пишем
  const sent =
    r.status === 'applied' && r.my_decision !== 'earlier'
      ? `📨 Отклик отправлен${r.applied_at ? ` ${thaiDate(r.applied_at)}` : ''}`
      : '';
  return [`<a href="${r.url}"><b>${esc(r.title)}</b></a>`, meta, flags, verdict, mine, sent, FINAL[r.status] ?? '']
    .filter(Boolean)
    .join('\n');
}
// Общий код сообщения с письмом в Telegram: W5 «Format letter» и W3 «Apply sent».
// Подключается после n8n/shared/card.js (нужны esc и thaiDate):
//   // @include n8n/shared/card.js
//   // @include n8n/shared/letter.js

const LETTER_HEAD = { new: '✉️ Письмо', redo: '🔄 Новый вариант письма', revise: '✏️ Письмо с правкой' };

// r: строка вакансии + { ok, letter, problem, mode, instruction }. Письмо — в <pre>: копируется одним нажатием.
// После «📨 Отправил» (status = applied) подсказки заменяет строка «📨 Отклик отправлен …»
function letterText(r) {
  const head = `${LETTER_HEAD[r.mode] ?? LETTER_HEAD.new} · <a href="${r.url}">${esc(r.title)}</a> · ${esc(r.company)}`;
  if (!r.ok) {
    return [head, `⚠️ Письмо не получилось: ${esc(r.problem)}`, 'Нажми «🔄 Переписать», чтобы попробовать ещё раз.'].join('\n');
  }
  const sent = r.status === 'applied';
  const closed = r.status === 'archived';
  return [
    head,
    r.mode === 'revise' && r.instruction ? `<i>Пожелание: «${esc(r.instruction)}»</i>` : '',
    `<pre>${esc(r.letter)}</pre>`,
    !sent && !closed && r.has_test ? '📝 У вакансии тест — ответы в форме отклика на hh.' : '',
    sent
      ? `📨 Отклик отправлен${r.applied_at ? ` ${thaiDate(r.applied_at)}` : ''}`
      : closed
        ? '🔒 Вакансия закрыта на hh — отклик уже не отправить'
        : '<i>Нажми на письмо — скопируется. Поправить — ответь на это сообщение.</i>',
  ]
    .filter(Boolean)
    .join('\n');
}
// Общий код разбора страницы вакансии hh: W1 «Parse vacancy» и W6 «Archive status».
// В Code-ноду попадает строкой «// @include n8n/shared/hh.js».

// HTML-сущности раскодируем за один проход: иначе &amp;quot; станет кавычкой и сломает JSON
const NAMED = { quot: '"', amp: '&', lt: '<', gt: '>', apos: "'", nbsp: '\u00a0' };
function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code <= 0x10ffff ? String.fromCodePoint(code) : m;
    }
    return NAMED[e.toLowerCase()] ?? m;
  });
}

// Ответ HTTP Request «Vacancy page» → { v: vacancyFull.vacancy, test } или { error, statusCode }
function parsePage(res) {
  const html = String(res.data ?? res.body ?? '');
  if (res.statusCode !== 200) return { error: `страница: HTTP ${res.statusCode}`, statusCode: res.statusCode };
  const tpl = html.match(/<template[^>]*id="HH-Lux-InitialState"[^>]*>([\s\S]*?)<\/template>/);
  if (!tpl) return { error: 'страница: нет HH-Lux-InitialState' };
  try {
    const state = JSON.parse(decodeEntities(tpl[1]));
    const v = state?.vacancyView?.vacancyFull?.vacancy;
    if (!v?.description) return { error: 'страница: нет описания' };
    return { v, test: state?.applicantVacancyResponseStatuses?.[String(v.vacancyId)]?.test };
  } catch (e) {
    return { error: `страница: ${e.message}` };
  }
}

const candidates = $('Plan').first().json.check;
const responses = $input.all().map((i) => i.json);

return candidates.flatMap((r, i) => {
  const res = responses[i] ?? {};
  let closed = res.statusCode === 404 || res.statusCode === 410;
  if (!closed && res.statusCode === 200) {
    const page = parsePage(res);
    closed = Boolean(page.v && (page.v.status?.archived || page.v.closedForApplicants));
  }
  if (!closed) return [];
  const updated = { ...r, status: 'archived' };
  return [
    {
      json: {
        id: r.id,
        tg_message_id: r.tg_message_id,
        tg_letter_id: r.tg_letter_id || null,
        cardText: cardText(updated),
        letterText: r.letter ? letterText({ ...updated, ok: true, mode: 'new' }) : '',
      },
    },
  ];
});

// W6 · Archived done — status = archived для закрытых на hh.
// Нода: Code, режим «Run Once for All Items». Выход: обновления для «Save archived».

return $('Archive status')
  .all()
  .map((i) => ({ json: { id: i.json.id, status: 'archived' } }));

// W6 · Summary — утренняя сводка за сутки (10:00 по Таиланду = 06:00 МСК).
// Нода: Code, режим «Run Once for All Items». Выполняется последней (ветки выше — устаревшие и закрытые).
// Вход: «All rows» (таблица до правок этого запуска), «Plan», «Expire rows» / «Archive status» (если были),
//       «Executions» — запуски n8n из публичного API, $input — «Tunnel» (проверка туннеля ngrok).
// Выход: одно сообщение { text, silent }. Без звука, если сбоев нет (решение пользователя 07.10.2026).

// Расписание сбора W1 по Москве (UTC+3, без перехода на летнее время), решение пользователя 07.10.2026:
// днём 07:00–17:30 каждые 30 мин, ночью 18, 20, 22, 00, 02, 04, 06 — 29 сборов в сутки.
// Держать в синхроне с Schedule W1 в scripts/build-workflows.mjs.
// Общий код W6 «Summary» и W7 «Render»: строка «// @include n8n/shared/schedule.js».

const COLLECT_STEP = 30 * 60 * 1000;

// Момент t (мс, кратен 30 мин) — сбор по расписанию?
function isCollectSlot(t) {
  const msk = new Date(t + 3 * 3600 * 1000);
  const h = msk.getUTCHours();
  const m = msk.getUTCMinutes();
  return h >= 7 && h < 18 ? m % 30 === 0 : m === 0 && h % 2 === 0;
}

// Сколько сборов по расписанию в промежутке (from, to]
function countCollectSlots(from, to) {
  let n = 0;
  for (let t = Math.floor(from / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP; t <= to; t += COLLECT_STEP) {
    if (isCollectSlot(t)) n++;
  }
  return n;
}

// Ближайший сбор по расписанию после момента t
function nextCollect(t) {
  let s = Math.floor(t / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP;
  while (!isCollectSlot(s)) s += COLLECT_STEP;
  return s;
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const from = (name) => {
  try {
    return $(name).all().map((i) => i.json);
  } catch {
    return []; // ветка не выполнялась: устаревших или закрытых не было
  }
};

const DAY = 24 * 3600 * 1000;
const now = Date.now();
const since = now - DAY;
const at = (s) => Date.parse(s) || 0;
const rows = $('All rows').all().map((i) => i.json).filter((r) => r.id);
const expired = new Set(from('Expire rows').map((r) => r.id));
const archived = new Set(from('Archive status').map((r) => r.id));

// Воронка: новые строки за сутки (кроме бэкфилла seen) → отсеяно фильтром → оценено нейросетью
const fresh = rows.filter((r) => at(r.createdAt) >= since && r.status !== 'seen');
const rejected = fresh.filter((r) => r.status === 'rejected');
const reasons = {};
for (const r of rejected) {
  for (const reason of String(r.reasons).split(', ').filter(Boolean)) {
    const key = reason.replace(/:.*$/, '');
    reasons[key] = (reasons[key] ?? 0) + 1;
  }
}
const topReasons = Object.entries(reasons)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 4)
  .map(([k, n]) => `${esc(k)} ${n}`)
  .join(' · ');
// Время оценки — card_at (пишет W2); у строк до этапа 5 его нет — берём время создания
const scored = rows.filter((r) => r.decision && at(r.card_at || r.createdAt) >= since);
const count = (list, f) => list.filter(f).length;

// Решения пользователя за сутки (по времени последнего изменения строки) и отправленные отклики
const mine = rows.filter((r) => r.my_decision && at(r.updatedAt) >= since);
const sent = count(rows, (r) => at(r.applied_at) >= since);

// Хвосты после этого запуска
const tailsWaiting = count(rows, (r) => r.status === 'waiting' && !expired.has(r.id) && !archived.has(r.id));
const tailsApproved = count(rows, (r) => r.status === 'approved' && !archived.has(r.id));

// Теневой режим: оценки пользователя там, где решение нейросети известно
// («📨 откликался раньше» — my_decision = earlier — не сравниваем: отклик был до бота)
const shadow = rows.filter((r) => ['apply', 'maybe', 'skip'].includes(r.my_decision) && ['apply', 'maybe', 'skip'].includes(r.decision));
const agree = count(shadow, (r) => r.my_decision === r.decision);

// Сбои: запуски n8n за сутки (публичный API), туннель, хвост оценки нейросетью
const NAMES = {
  jobHunterS0Setup: 'S0 таблицы',
  jobHunterS1TgTst: 'S1 тест Telegram',
  jobHunterW0Check: 'W0 проверка hh',
  jobHunterW4Error: 'W4 тревоги',
  jobHunterW1Colle: 'W1 сбор',
  jobHunterW2Score: 'W2 оценка',
  jobHunterW3Teleg: 'W3 кнопки',
  jobHunterW5Lettr: 'W5 письма',
  jobHunterW6Summ1: 'W6 сводка',
  jobHunterW7Menu1: 'W7 меню',
};
const executionsBody = $('Executions').first().json;
const executions = (executionsBody.data ?? []).filter((e) => at(e.startedAt) >= since);
const errors = executions.filter((e) => e.status === 'error' || e.status === 'crashed');
const errorsBy = {};
for (const e of errors) errorsBy[NAMES[e.workflowId] ?? e.workflowId] = (errorsBy[NAMES[e.workflowId] ?? e.workflowId] ?? 0) + 1;

// Сборы W1 по расписанию (n8n/shared/schedule.js). Окно — сутки до «сейчас − 10 мин»:
// сбор в 06:00 идёт одновременно со сводкой и ещё не закончился
const windowEnd = now - 10 * 60 * 1000;
const windowStart = windowEnd - DAY;
const expected = countCollectSlots(windowStart, windowEnd);
const collected = count(
  executionsBody.data ?? [],
  (e) =>
    e.workflowId === 'jobHunterW1Colle' &&
    e.status === 'success' &&
    e.mode === 'trigger' &&
    at(e.startedAt) > windowStart &&
    at(e.startedAt) <= windowEnd,
);
// Ждут оценки дольше 30 мин: W2 запускается сразу после сбора, свежие строки detailed — норма
const pendingScore = count(rows, (r) => r.status === 'detailed' && at(r.createdAt) < now - 30 * 60 * 1000);
const tunnelCode = $input.first().json.statusCode;
const tunnelOk = !$env.NGROK_DOMAIN || tunnelCode === 403; // 403 = туннель жив, политика не пускает чужих

const problems = [];
if (executionsBody.error || !executionsBody.data) problems.push('нет данных о запусках n8n');
if (collected < expected) problems.push(`сборов ${collected} из ${expected}`);
if (errors.length)
  problems.push(
    `ошибок ${errors.length} (${Object.entries(errorsBy)
      .map(([k, n]) => `${k} ${n}`)
      .join(' · ')})`,
  );
if (!tunnelOk) problems.push(`туннель не отвечает (${tunnelCode ?? 'нет ответа'}) — кнопки не работают`);
if (pendingScore) problems.push(`ждут оценки нейросетью: ${pendingScore}`);

const date = new Date(now + 7 * 3600 * 1000).toISOString().slice(0, 10).split('-').reverse().slice(0, 2).join('.');
const lines = [
  `☀️ <b>Сводка за сутки</b> · ${date}`,
  `🔎 Новых вакансий: ${fresh.length} → фильтр отсеял ${rejected.length}${topReasons ? ` (${topReasons})` : ''}`,
  `🤖 Оценено: ${scored.length}${scored.length ? ` — 🟢 ${count(scored, (r) => r.decision === 'apply')} · 🟡 ${count(scored, (r) => r.decision === 'maybe')} · 🔴 ${count(scored, (r) => r.decision === 'skip')}` : ''}${count(scored, (r) => r.decision === 'error') ? ` · ⚠️ ${count(scored, (r) => r.decision === 'error')}` : ''}`,
  `👤 Твои решения: ✅ ${count(mine, (r) => r.my_decision === 'apply')} · 🤔 ${count(mine, (r) => r.my_decision === 'maybe')} · ❌ ${count(mine, (r) => r.my_decision === 'skip')} · 📨 отправлено ${sent}${count(mine, (r) => r.my_decision === 'earlier') ? ` · 📨 раньше ${count(mine, (r) => r.my_decision === 'earlier')}` : ''}`,
  `⏳ Хвосты: без решения ${tailsWaiting} · ✅ без отклика ${tailsApproved}`,
  expired.size || archived.size ? `⌛ Устарели: ${expired.size} · 🔒 закрылись на hh: ${archived.size}` : '',
  shadow.length >= 50
    ? `🧪 Теневой режим: ${shadow.length}/50, совпало ${agree} (${Math.round((agree / shadow.length) * 100)}%) — пора разбирать, напиши Claude`
    : `🧪 Теневой режим: ${shadow.length}/50${shadow.length ? `, совпало ${agree} (${Math.round((agree / shadow.length) * 100)}%)` : ''}`,
  problems.length ? `⚠️ Сбои: ${problems.join(' · ')}` : `⚙️ Сборов ${collected} из ${expected}, ошибок нет, туннель работает`,
];

return [{ json: { text: lines.filter(Boolean).join('\n'), silent: problems.length === 0 } }];
